    Specification(standard_code='7', spec_code='b', standard_title='Personnel Roles, Responsibilities, and Evaluation', spec_text='Essential program roles include administration, curriculum development and review, instruction, field supervision, program planning, program evaluation, student advising, and student evaluation. Provide the following: A brief description of how these essential roles are fulfilled in the program A table matching faculty and staff positions and names with these roles.', program_level='associate', version="2025"),
